window.AUTH=window.AUTH||{};window.AUTH["12-761"]={"d":"12-761","id":"2013/12-761","n":"Pom Wonderful, LLC v. The Coca-Cola Company","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting neither party","date":"2014-03-03","url":"https://www.justice.gov/osg/media/206871/dl?inline","side":"us","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/pom-wonderful-v-coca-cola-co-amicus-merits","n":60}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep573/usrep573102/usrep573102.pdf","tr":true,"items":[{"t":"case","label":"Altria Grp., Inc. v. Good","cite":"555 U.S. 70","y":2008,"id":"2008/07-562","sc":1,"op":2,"sum":"The Court held that the Federal Cigarette Labeling and Advertising Act did not preempt all claims related to \"smoking and health\" under the Maine Unfair Trade Practices Act.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Bates v. Dow Agrosciences LLC","cite":"544 U.S. 431","y":2005,"id":"2004/03-388","sc":1,"sum":"The Court held that the peanut farmers could sue Dow in state court.","sumSrc":"Oyez","by":{"0":"27, 30"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"ar":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Cottrell, Ltd. v. Biotrol Int’l, Inc.","cite":"191 F.3d 1248","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/191/1248/","by":{"0":"28"}},{"t":"case","label":"English v. General Elec. Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Fidelity Fed. Sav. & Loan Ass’n v. de la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"sum":"The Board's due-on-sale regulation pre-empts conflicting state limitations on the due-on-sale practices of federal savings and loan associations, and thus bars application of the Wellenkamp rule to such associations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Freightliner Corp. v. Myrick","cite":"514 U.S. 280","y":1995,"id":"1994/94-286","sc":1,"sum":"In separate state common-law suits, respondents alleged that the absence of an antilock braking system (ABS) in tractor-trailers manufactured by petitioners constituted a negligent design defect that caused accidents injuring one respondent and killing another's spouse. The District Court granted summary judgments for petitioners, holding that respondents' claims were pre-empted by the National Traffic and Motor …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"op":2,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"20, 24"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"27, 29"}},{"t":"case","label":"Hillsborough Cnty. v. Automated Med. Labs., Inc.","cite":"471 U.S. 707","y":1985,"id":"1984/83-1925","sc":1,"sum":"Appellant county's ordinances and implementing regulations are not pre-empted by the federal regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Holk v. Snapple Beverage Corp.","cite":"575 F.3d 329","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/575/329/","by":{"0":"2"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"op":2,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"0":"11, 20, 24"}},{"t":"case","label":"Kurns v. Railroad Friction Prods. Corp.","cite":"132 S. Ct. 1261","y":2012,"id":"2011/10-879","sc":1,"sum":"The Court held that the Locomotive Inspection Act preempts state law design defect claims and state law failure to warn claims.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"op":1,"ar":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"131 S. Ct. 2567","y":2011,"id":"2010/09-993","sc":1,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"0":"22, 32"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Reiter v. Cooper","cite":"507 U.S. 258","y":1993,"id":"1992/91-1496","sc":1,"sum":"The Interstate Commerce Act (ICA) requires that motor common carriers charge the tariff rates they file with the Interstate Commerce Commission (ICC), 49 U. S. C. § 10762, and that such rates be \"reasonable,\" § 10701(a). Between 1984 and 1986, petitioner shippers tendered shipments to Carolina Motor Express, Inc., a motor carrier subject to ICC regulation, at negotiated rates that were lower than the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Schering-Plough Healthcare Prods., Inc. v. Schwarz Pharma, Inc.","cite":"586 F.3d 500","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/586/500/","by":{"0":"27"}},{"t":"case","label":"62 Cases of Jam v. United States","cite":"340 U.S. 593","y":1951,"id":"scdb/1950-050","sc":1,"op":2,"sum":"It was not \"misbranded\" within the meaning of § 403. Federal Security Administrator v. Quaker Oats Co., 318 U. S. 218, distinguished. Pp. 593-601. 183 F. 2d 1014, reversed. On a libel by the United States against certain food products under § 304 of the Federal Food, Drug, and Cosmetic Act, the District Court held that they were not \"misbranded\" within the meaning of § 403. 87 F. Supp. 735. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"op":7,"ar":7,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","stext":{"head":"§301. Short title","paras":[[0,"This chapter may be cited as the Federal Food, Drug, and Cosmetic Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§301. Short title","tname":"Food and Drugs","by":{"0":"1, 2"}},{"t":"usc","label":"21 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/21/321","by":{"0":"2"}},{"t":"usc","label":"21 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/21/331","subs":["(a)","(c)"],"stext":{"head":"§331. Prohibited acts","paras":[[0,"The following acts and the causing thereof are prohibited:"],[0,"(a) The introduction or delivery for introduction into interstate commerce of any food, drug, device, tobacco product, or cosmetic that is adulterated or misbranded."],[0,"(b) The adulteration or misbranding of any food, drug, device, tobacco product, or cosmetic in interstate commerce."],[0,"(c) The receipt in interstate commerce of any food, drug, device, tobacco product, or cosmetic that is adulterated or misbranded, and the delivery or proffered delivery thereof for pay or otherwise."],[0,"(d) The introduction or delivery for introduction into interstate commerce of any article in violation of section 344, 350d, 355,,1 360bbb–3, or 364c of this title."],[0,"(e) The refusal to permit access to or copying of any record as required by section 350a, 350c, 350f(j), 350e, 354, 360bbb–3, 364a, 373, 374(a), 379aa, or 379aa–1 of this title; or the failure to establish or maintain any record, or make any report, required under section 350a, 350c(b), 350f, 350e, 354, 355(i) or (k), 360b(a)(4)(C), 360b(j), (l) or (m), 360ccc–1(i), 360e(f), 360i, 360bbb–3, 364a, 364g, 379aa, 379aa–1, 387i, or 387t of this title or the refusal to permit access to or verification or copying of any such required record; or the violation of any recordkeeping requirement under section 2223 2 of this title (except when such violation is committed by a farm)."],[0,"(f) The refusal to permit entry or inspection as authorized by section 374 of this title."],[0,"(g) The manufacture within any Territory of any food, drug, device, tobacco product, or cosmetic that is adulterated or misbranded."],[0,"(h) The giving of a guaranty or undertaking referred to in section 333(c)(2) of this title, which guaranty or undertaking is false, except by a person who relied upon a guaranty or undertaking to the same effect signed by, and containing the name and address of, the person residing in the United States from whom he received in good faith the food, drug, device, tobacco product, or cosmetic; or the giving of a guaranty or undertaking referred to in section 333(c)(3) of this title, which guaranty or undertaking is false."],[0,"(i)(1) Forging, counterfeiting, simulating, or falsely representing, or without proper authority using any mark, stamp, tag, label, or other identification device authorized or required by regulations promulgated under the provisions of section 344 or 379e of this title."],[0,"(2) Making, selling, disposing of, or keeping in possession, control, or custody, or concealing any punch, die, plate, stone, or other thing designed to print, imprint, or reproduce the trademark, trade name, or other identifying mark, imprint, or device of another or any likeness of any of the foregoing upon any drug or container or labeling thereof so as to render such drug a counterfeit drug."],[0,"(3) The doing of any act which causes a drug to be a counterfeit drug, or the sale or dispensing, or the holding for sale or dispensing, of a counterfeit drug."],[0,"(j) The using by any person to his own advantage, or revealing, other than to the Secretary or officers or employees of the Department, or to the courts when relevant in any judicial proceeding under this chapter, any information acquired under authority of section 344, 348, 350a, 350c, 355, 360, 360b, 360c, 360d, 360e, 360f, 360h, 360i, 360j, 360ccc, 360ccc–1, 360ccc–2, 374, 379, 379e, 387d, 387e, 387f, 387g, 387h, 387i, or 387t(b) of this title concerning any method or process which as a trade secret is entitled to protection; or the violating of section 346a(i)(2) of this title or any regulation issued under that section..1This paragraph does not authorize the withholding of information from either House of Congress or from, to the extent of matter within its jurisdiction, any committee or subcommittee of such committee or any joint committee of Congress or any subcommittee of such joint committee."],[0,"(k) The alteration, mutilation, destruction, obliteration, or removal of the whole or any part of the labeling of, or the doing of any other act with respect to, a food, drug, device, tobacco product, or cosmetic, if such act is done while such article is held for sale (whether or not the first sale) after shipment in interstate commerce and results in such article being adulterated or misbranded."],[0,"(l) Repealed. Pub. L. 105–115, title IV, §421, Nov. 21, 1997, 111 Stat. 2380."],[0,"(m) The sale or offering for sale of colored oleomargarine or colored margarine, or the possession or serving of colored oleomargarine or colored margarine in violation of subsections (b) or (c) of section 347 of this title."],[0,"(n) The using, in labeling, advertising or other sales promotion of any reference to any report or analysis furnished in compliance with section 374 of this title."],[0,"(o) In the case of a prescription drug distributed or offered for sale in interstate commerce, the failure of the manufacturer, packer, or distributor thereof to maintain for transmittal, or to transmit, to any practitioner licensed by applicable State law to administer such drug who makes written request for information as to such drug, true and correct copies of all printed matter which is required to be included in any package in which that drug is distributed or sold, or such other printed matter as is approved by the Secretary. Nothing in this paragraph shall be construed to exempt any person from any labeling requirement imposed by or under other provisions of this chapter."],[0,"(p) The failure to register in accordance with section 360 or 387e of this title, the failure to provide any information required by section 360(j), 360(k), 387e(i), or 387e(j) of this title, or the failure to provide a notice required by section 360(j)(2) or 387e(i)(3) of this title."],[0,"(q)(1) The failure or refusal—"],[1,"(A) to comply with any requirement prescribed under section 360h, 360j(g), 387c(b), 387g, 387h, or 387o of this title;"],[1,"(B) to furnish any notification or other material or information required by or under section 360i, 360j(g), 387d, 387i, or 387t of this title; or"],[1,"(C) to comply with a requirement under section 360l or 387m of this title."],[0,"(2) With respect to any device or tobacco product, the submission of any report that is required by or under this chapter that is false or misleading in any material respect."],[0,"(3) The failure to comply with any requirement under section 360n–2(b)(2) of this title (relating to ensuring device cybersecurity)."],[0,"(r) The movement of a device, drug, or tobacco product in violation of an order under section 334(g) of this title or the removal or alteration of any mark or label required by the order to identify the device, drug, or tobacco product as detained."],[0,"(s) The failure to provide the notice required by section 350a(c) or 350a(e) of this title, the failure to make the reports required by section 350a(f)(1)(B) of this title, the failure to retain the records required by section 350a(b)(4) of this title, or the failure to meet the requirements prescribed under section 350a(f)(3) of this title."],[0,"(t) The importation of a drug in violation of section 381(d)(1) of this title, the sale, purchase, or trade of a drug or drug sample or the offer to sell, purchase, or trade a drug or drug sample in violation of section 353(c) of this title, the sale, purchase, or trade of a coupon, the offer to sell, purchase, or trade such a coupon, or the counterfeiting of such a coupon in violation of section 353(c)(2) of this title, the distribution of a drug sample in violation of section 353(d) of this title or the failure to otherwise comply with the requirements of section 353(d) of this title, the distribution of drugs in violation of section 353(e) of this title, failure to comply with the requirements under section 360eee–1 of this title, the failure to comply with the requirements under section 360eee–3 of this title, as applicable, or the failure to otherwise comply with the requirements of section 353(e) of this title."],[0,"(u) The failure to comply with any requirements of the provisions of, or any regulations or orders of the Secretary, under section 360b(a)(4)(A), 360b(a)(4)(D), or 360b(a)(5) of this title."],[0,"(v) The introduction or delivery for introduction into interstate commerce of a dietary supplement that is unsafe under section 350b of this title."],[0,"(w) The making of a knowingly false statement in any statement, certificate of analysis, record, or report required or requested under section 381(d)(3) of this title; the failure to submit a certificate of analysis as required under such section; the failure to maintain records or to submit records or reports as required by such section; the release into interstate commerce of any article or portion thereof imported into the United States under such section or any finished product made from such article or portion, except for export in accordance with section 381(e) or 382 of this title, or with section 262(h) of title 42; or the failure to so export or to destroy such an article or portions thereof, or such a finished product."],[0,"(x) The falsification of a declaration of conformity submitted under section 360d(c) of this title or the failure or refusal to provide data or information requested by the Secretary under paragraph (3) of such section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/331?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§331. Prohibited acts","tname":"Food and Drugs","by":{"0":"2, 2"}},{"t":"usc","label":"21 U.S.C. § 337","url":"https://www.law.cornell.edu/uscode/text/21/337","subs":["(a)","(b)"],"stext":{"head":"§337. Proceedings in name of United States; provision as to subpoenas","paras":[[0,"(a) Except as provided in subsection (b), all such proceedings for the enforcement, or to restrain violations, of this chapter shall be by and in the name of the United States. Subpoenas for witnesses who are required to attend a court of the United States, in any district, may run into any other district in any proceeding under this section."],[0,"(b)(1) A State may bring in its own name and within its jurisdiction proceedings for the civil enforcement, or to restrain violations, of section 341, 343(b), 343(c), 343(d), 343(e), 343(f), 343(g), 343(h), 343(i), 343(k), 343(q), or 343(r) of this title if the food that is the subject of the proceedings is located in the State."],[0,"(2) No proceeding may be commenced by a State under paragraph (1)—"],[1,"(A) before 30 days after the State has given notice to the Secretary that the State intends to bring such proceeding,"],[1,"(B) before 90 days after the State has given notice to the Secretary of such intent if the Secretary has, within such 30 days, commenced an informal or formal enforcement action pertaining to the food which would be the subject of such proceeding, or"],[1,"(C) if the Secretary is diligently prosecuting a proceeding in court pertaining to such food, has settled such proceeding, or has settled the informal or formal enforcement action pertaining to such food."],[0,"In any court proceeding described in subparagraph (C), a State may intervene as a matter of right."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/337?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§337. Proceedings in name of United States; provision as to subpoenas","tname":"Food and Drugs","by":{"0":"4, 25"}},{"t":"usc","label":"21 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/21/341","stext":{"head":"§341. Definitions and standards for food","paras":[[0,"Whenever in the judgment of the Secretary such action will promote honesty and fair dealing in the interest of consumers, he shall promulgate regulations fixing and establishing for any food, under its common or usual name so far as practicable, a reasonable definition and standard of identity, a reasonable standard of quality, or reasonable standards of fill of container. No definition and standard of identity and no standard of quality shall be established for fresh or dried fruits, fresh or dried vegetables, or butter, except that definitions and standards of identity may be established for avocadoes, cantaloupes, citrus fruits, and melons. In prescribing any standard of fill of container, the Secretary shall give due consideration to the natural shrinkage in storage and in transit of fresh natural food and to need for the necessary packing and protective material. In the prescribing of any standard of quality for any canned fruit or canned vegetable, consideration shall be given and due allowance made for the differing characteristics of the several varieties of such fruit or vegetable. In prescribing a definition and standard of identity for any food or class of food in which optional ingredients are permitted, the Secretary shall, for the purpose of promoting honesty and fair dealing in the interest of consumers, designate the optional ingredients which shall be named on the label. Any definition and standard of identity prescribed by the Secretary for avocadoes, cantaloupes, citrus fruits, or melons shall relate only to maturity and to the effects of freezing."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/341?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§341. Definitions and standards for food","tname":"Food and Drugs","by":{"0":"3"}},{"t":"usc","label":"21 U.S.C. § 343","url":"https://www.law.cornell.edu/uscode/text/21/343","subs":["(a)(1)","(i)","(i)(1)","(i)(2)"],"stext":{"head":"§343. Misbranded food","paras":[[0,"A food shall be deemed to be misbranded—"],[0,"(a) False or misleading label"],[0,"If (1) its labeling is false or misleading in any particular, or (2) in the case of a food to which section 350 of this title applies, its advertising is false or misleading in a material respect or its labeling is in violation of section 350(b)(2) of this title."],[0,"(b) Offer for sale under another name"],[0,"If it is offered for sale under the name of another food."],[0,"(c) Imitation of another food"],[0,"If it is an imitation of another food, unless its label bears, in type of uniform size and prominence, the word \"imitation\" and, immediately thereafter, the name of the food imitated."],[0,"(d) Misleading container"],[0,"If its container is so made, formed, or filled as to be misleading."],[0,"(e) Package form"],[0,"If in package form unless it bears a label containing (1) the name and place of business of the manufacturer, packer, or distributor; and (2) an accurate statement of the quantity of the contents in terms of weight, measure, or numerical count, except that under clause (2) of this paragraph reasonable variations shall be permitted, and exemptions as to small packages shall be established, by regulations prescribed by the Secretary."],[0,"(f) Prominence of information on label"],[0,"If any word, statement, or other information required by or under authority of this chapter to appear on the label or labeling is not prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or devices, in the labeling) and in such terms as to render it likely to be read and understood by the ordinary individual under customary conditions of purchase and use."],[0,"(g) Representation as to definition and standard of identity"],[0,"If it purports to be or is represented as a food for which a definition and standard of identity has been prescribed by regulations as provided by section 341 of this title, unless (1) it conforms to such definition and standard, and (2) its label bears the name of the food specified in the definition and standard, and, insofar as may be required by such regulations, the common names of optional ingredients (other than spices, flavoring, and coloring) present in such food."],[0,"(h) Representation as to standards of quality and fill of container"],[0,"If it purports to be or is represented as—"],[1,"(1) a food for which a standard of quality has been prescribed by regulations as provided by section 341 of this title, and its quality falls below such standard, unless its label bears, in such manner and form as such regulations specify, a statement that it falls below such standard;"],[1,"(2) a food for which a standard or standards of fill of container have been prescribed by regulations as provided by section 341 of this title, and it falls below the standard of fill of container applicable thereto, unless its label bears, in such manner and form as such regulations specify, a statement that it falls below such standard; or"],[1,"(3) a food that is pasteurized unless—"],[2,"(A) such food has been subjected to a safe process or treatment that is prescribed as pasteurization for such food in a regulation promulgated under this chapter; or"],[2,"(B)(i) such food has been subjected to a safe process or treatment that—"],[3,"(I) is reasonably certain to achieve destruction or elimination in the food of the most resistant microorganisms of public health significance that are likely to occur in the food;"],[3,"(II) is at least as protective of the public health as a process or treatment described in subparagraph (A);"],[3,"(III) is effective for a period that is at least as long as the shelf life of the food when stored under normal and moderate abuse conditions; and"],[3,"(IV) is the subject of a notification to the Secretary, including effectiveness data regarding the process or treatment; and"],[2,"(ii) at least 120 days have passed after the date of receipt of such notification by the Secretary without the Secretary making a determination that the process or treatment involved has not been shown to meet the requirements of subclauses (I) through (III) of clause (i)."],[0,"For purposes of paragraph (3), a determination by the Secretary that a process or treatment has not been shown to meet the requirements of subclauses (I) through (III) of subparagraph (B)(i) shall constitute final agency action under such subclauses."],[0,"(i) Label where no representation as to definition and standard of identity"],[0,"Unless its label bears (1) the common or usual name of the food, if any there be, and (2) in case it is fabricated from two or more ingredients, the common or usual name of each such ingredient and if the food purports to be a beverage containing vegetable or fruit juice, a statement with appropriate prominence on the information panel of the total percentage of such fruit or vegetable juice contained in the food; except that spices, flavorings, and colors not required to be certified under section 379e(c) of this title 1 unless sold as spices, flavorings, or such colors, may be designated as spices, flavorings, and colorings without naming each. To the extent that compliance with the requirements of clause (2) of this paragraph is impracticable, or results in deception or unfair competition, exemptions shall be established by regulations promulgated by the Secretary."],[0,"(j) Representation for special dietary use"],[0,"If it purports to be or is represented for special dietary uses, unless its label bears such information concerning its vitamin, mineral, and other dietary properties as the Secretary determines to be, and by regulations prescribes as, necessary in order fully to inform purchasers as to its value for such uses."],[0,"(k) Artificial flavoring, artificial coloring, or chemical preservatives"],[0,"If it bears or contains any artificial flavoring, artificial coloring, or chemical preservative, unless it bears labeling stating that fact, except that to the extent that compliance with the requirements of this paragraph is impracticable, exemptions shall be established by regulations promulgated by the Secretary. The provisions of this paragraph and paragraphs (g) and (i) with respect to artificial coloring shall not apply in the case of butter, cheese, or ice cream. The provisions of this paragraph with respect to chemical preservatives shall not apply to a pesticide chemical when used in or on a raw agricultural commodity which is the produce of the soil."],[0,"(l) Pesticide chemicals on raw agricultural commodities"],[0,"If it is a raw agricultural commodity which is the produce of the soil, bearing or containing a pesticide chemical applied after harvest, unless the shipping container of such commodity bears labeling which declares the presence of such chemical in or on such commodity and the common or usual name and the function of such chemical, except that no such declaration shall be required while such commodity, having been removed from the shipping container, is being held or displayed for sale at retail out of such container in accordance with the custom of the trade."],[0,"(m) Color additives"],[0,"If it is a color additive, unless its packaging and labeling are in conformity with such packaging and labeling requirements, applicable to such color additive, as may be contained in regulations issued under section 379e of this title."],[0,"(n) Packaging or labeling of drugs in violation of regulations"],[0,"If its packaging or labeling is in violation of an applicable regulation issued pursuant to section 1472 or 1473 of title 15."],[0,"(o) Repealed. Pub. L. 106–554, §1(a)(1) [title V, §517], Dec. 21, 2000, 114 Stat. 2763, 2763A–73"],[0,"(p) Repealed. Pub. L. 104–124, §1, Apr. 1, 1996, 110 Stat. 882"],[0,"(q) Nutrition information"],[0,"(1) Except as provided in subparagraphs (3), (4), and (5), if it is a food intended for human consumption and is offered for sale, unless its label or labeling bears nutrition information that provides—"],[1,"(A)(i) the serving size which is an amount customarily consumed and which is expressed in a common household measure that is appropriate to the food, or"],[1,"(ii) if the use of the food is not typically expressed in a serving size, the common household unit of measure that expresses the serving size of the food,"],[1,"(B) the number of servings or other units of measure per container,"],[1,"(C) the total number of calories—"],[2,"(i) derived from any source, and"],[2,"(ii) derived from the total fat,"],[1,"in each serving size or other unit of measure of the food,"],[1,"(D) the amount of the following nutrients: Total fat, saturated fat, cholesterol, sodium, total carbohydrates, complex carbohydrates, sugars, dietary fiber, and total protein contained in each serving size or other unit of measure,"],[1,"(E) any vitamin, mineral, or other nutrient required to be placed on the label and labeling of food under this chapter before October 1, 1990, if the Secretary determines that such information will assist consumers in maintaining healthy dietary practices."],[0,"The Secretary may by regulation require any information required to be placed on the label or labeling by this subparagraph or subparagraph (2)(A) to be highlighted on the label or labeling by larger type, bold type, or contrasting color if the Secretary determines that such highlighting will assist consumers in maintaining healthy dietary practices."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/343?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§343. Misbranded food","tname":"Food and Drugs","by":{"0":"2, 19, 25, 2, 4, 6, 8, 29, 8, 19, 2, 4, 2, 4, 3"}},{"t":"usc","label":"21 U.S.C. § 343-1","url":"https://www.law.cornell.edu/uscode/text/21/343-1","subs":["(a)","(a)(2)","(a)(3)","(b)"],"by":{"0":"25, 27, 20, 20, 25"}},{"t":"usc","label":"21 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/21/371","subs":["(e)(1)(B)"],"by":{"0":"27"}},{"t":"usc","label":"7 U.S.C. § 136","url":"https://www.law.cornell.edu/uscode/text/7/136","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 101-535","url":"https://www.govinfo.gov/link/statute/104/2353","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 1501","url":"https://www.law.cornell.edu/uscode/text/15/1501","by":{"0":"1, 5, 17, 20, 30"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)","(a)(1)","(a)(1)(B)"],"stext":{"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","paras":[[0,"(a) Civil action"],[0,"(1) Any person who, on or in connection with any goods or services, or any container for goods, uses in commerce any word, term, name, symbol, or device, or any combination thereof, or any false designation of origin, false or misleading description of fact, or false or misleading representation of fact, which—"],[1,"(A) is likely to cause confusion, or to cause mistake, or to deceive as to the affiliation, connection, or association of such person with another person, or as to the origin, sponsorship, or approval of his or her goods, services, or commercial activities by another person, or"],[1,"(B) in commercial advertising or promotion, misrepresents the nature, characteristics, qualities, or geographic origin of his or her or another person's goods, services, or commercial activities,"],[0,"shall be liable in a civil action by any person who believes that he or she is or is likely to be damaged by such act."],[0,"(2) As used in this subsection, the term \"any person\" includes any State, instrumentality of a State or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(3) In a civil action for trade dress infringement under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that the matter sought to be protected is not functional."],[0,"(b) Importation"],[0,"Any goods marked or labeled in contravention of the provisions of this section shall not be imported into the United States or admitted to entry at any customhouse of the United States. The owner, importer, or consignee of goods refused entry at any customhouse under this section may have any recourse by protest or appeal that is given under the customs revenue laws or may have the remedy given by this chapter in cases involving goods refused entry or seized."],[0,"(c) Dilution by blurring; dilution by tarnishment"],[0,"(1) Injunctive relief"],[1,"Subject to the principles of equity, the owner of a famous mark that is distinctive, inherently or through acquired distinctiveness, shall be entitled to an injunction against another person who, at any time after the owner's mark has become famous, commences use of a mark or trade name in commerce that is likely to cause dilution by blurring or dilution by tarnishment of the famous mark, regardless of the presence or absence of actual or likely confusion, of competition, or of actual economic injury."],[0,"(2) Definitions"],[1,"(A) For purposes of paragraph (1), a mark is famous if it is widely recognized by the general consuming public of the United States as a designation of source of the goods or services of the mark's owner. In determining whether a mark possesses the requisite degree of recognition, the court may consider all relevant factors, including the following:"],[2,"(i) The duration, extent, and geographic reach of advertising and publicity of the mark, whether advertised or publicized by the owner or third parties."],[2,"(ii) The amount, volume, and geographic extent of sales of goods or services offered under the mark."],[2,"(iii) The extent of actual recognition of the mark."],[2,"(iv) Whether the mark was registered under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register."],[1,"(B) For purposes of paragraph (1), \"dilution by blurring\" is association arising from the similarity between a mark or trade name and a famous mark that impairs the distinctiveness of the famous mark. In determining whether a mark or trade name is likely to cause dilution by blurring, the court may consider all relevant factors, including the following:"],[2,"(i) The degree of similarity between the mark or trade name and the famous mark."],[2,"(ii) The degree of inherent or acquired distinctiveness of the famous mark."],[2,"(iii) The extent to which the owner of the famous mark is engaging in substantially exclusive use of the mark."],[2,"(iv) The degree of recognition of the famous mark."],[2,"(v) Whether the user of the mark or trade name intended to create an association with the famous mark."],[2,"(vi) Any actual association between the mark or trade name and the famous mark."],[1,"(C) For purposes of paragraph (1), \"dilution by tarnishment\" is association arising from the similarity between a mark or trade name and a famous mark that harms the reputation of the famous mark."],[0,"(3) Exclusions"],[1,"The following shall not be actionable as dilution by blurring or dilution by tarnishment under this subsection:"],[2,"(A) Any fair use, including a nominative or descriptive fair use, or facilitation of such fair use, of a famous mark by another person other than as a designation of source for the person's own goods or services, including use in connection with—"],[3,"(i) advertising or promotion that permits consumers to compare goods or services; or"],[3,"(ii) identifying and parodying, criticizing, or commenting upon the famous mark owner or the goods or services of the famous mark owner."],[2,"(B) All forms of news reporting and news commentary."],[2,"(C) Any noncommercial use of a mark."],[0,"(4) Burden of proof"],[1,"In a civil action for trade dress dilution under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that—"],[2,"(A) the claimed trade dress, taken as a whole, is not functional and is famous; and"],[2,"(B) if the claimed trade dress includes any mark or marks registered on the principal register, the unregistered matter, taken as a whole, is famous separate and apart from any fame of such registered marks."],[0,"(5) Additional remedies"],[1,"In an action brought under this subsection, the owner of the famous mark shall be entitled to injunctive relief as set forth in section 1116 of this title. The owner of the famous mark shall also be entitled to the remedies set forth in sections 1117(a) and 1118 of this title, subject to the discretion of the court and the principles of equity if—"],[2,"(A) the mark or trade name that is likely to cause dilution by blurring or dilution by tarnishment was first used in commerce by the person against whom the injunction is sought after October 6, 2006; and"],[2,"(B) in a claim arising under this subsection—"],[3,"(i) by reason of dilution by blurring, the person against whom the injunction is sought willfully intended to trade on the recognition of the famous mark; or"],[3,"(ii) by reason of dilution by tarnishment, the person against whom the injunction is sought willfully intended to harm the reputation of the famous mark."],[0,"(6) Ownership of valid registration a complete bar to action"],[1,"The ownership by a person of a valid registration under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register under this chapter shall be a complete bar to an action against that person, with respect to that mark, that—"],[2,"(A) is brought by another person under the common law or a statute of a State; and"],[2,"(B)(i) seeks to prevent dilution by blurring or dilution by tarnishment; or"],[2,"(ii) asserts any claim of actual or likely damage or harm to the distinctiveness or reputation of a mark, label, or form of advertisement."],[0,"(7) Savings clause"],[1,"Nothing in this subsection shall be construed to impair, modify, or supersede the applicability of the patent laws of the United States."],[0,"(d) Cyberpiracy prevention"],[0,"(1)(A) A person shall be liable in a civil action by the owner of a mark, including a personal name which is protected as a mark under this section, if, without regard to the goods or services of the parties, that person—"],[1,"(i) has a bad faith intent to profit from that mark, including a personal name which is protected as a mark under this section; and"],[1,"(ii) registers, traffics in, or uses a domain name that—"],[2,"(I) in the case of a mark that is distinctive at the time of registration of the domain name, is identical or confusingly similar to that mark;"],[2,"(II) in the case of a famous mark that is famous at the time of registration of the domain name, is identical or confusingly similar to or dilutive of that mark; or"],[2,"(III) is a trademark, word, or name protected by reason of section 706 of title 18 or section 220506 of title 36."],[0,"(B)(i) In determining whether a person has a bad faith intent described under subparagraph (A), a court may consider factors such as, but not limited to—"],[1,"(I) the trademark or other intellectual property rights of the person, if any, in the domain name;"],[1,"(II) the extent to which the domain name consists of the legal name of the person or a name that is otherwise commonly used to identify that person;"],[1,"(III) the person's prior use, if any, of the domain name in connection with the bona fide offering of any goods or services;"],[1,"(IV) the person's bona fide noncommercial or fair use of the mark in a site accessible under the domain name;"],[1,"(V) the person's intent to divert consumers from the mark owner's online location to a site accessible under the domain name that could harm the goodwill represented by the mark, either for commercial gain or with the intent to tarnish or disparage the mark, by creating a likelihood of confusion as to the source, sponsorship, affiliation, or endorsement of the site;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1125?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","tname":"Commerce and Trade","by":{"0":"1, 5, 17, 20, 30, 5, 5"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","stext":{"head":"§1127. Construction and definitions; intent of chapter","paras":[[0,"In the construction of this chapter, unless the contrary is plainly apparent from the context—"],[0,"The United States includes and embraces all territory which is under its jurisdiction and control."],[0,"The word \"commerce\" means all commerce which may lawfully be regulated by Congress."],[0,"The term \"principal register\" refers to the register provided for by sections 1051 to 1072 of this title, and the term \"supplemental register\" refers to the register provided for by sections 1091 to 1096 of this title."],[0,"The term \"person\" and any other word or term used to designate the applicant or other entitled to a benefit or privilege or rendered liable under the provisions of this chapter includes a juristic person as well as a natural person. The term \"juristic person\" includes a firm, corporation, union, association, or other organization capable of suing and being sued in a court of law."],[0,"The term \"person\" also includes the United States, any agency or instrumentality thereof, or any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States. The United States, any agency or instrumentality thereof, and any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The term \"person\" also includes any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The terms \"applicant\" and \"registrant\" embrace the legal representatives, predecessors, successors and assigns of such applicant or registrant."],[0,"The term \"Director\" means the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office."],[0,"The term \"related company\" means any person whose use of a mark is controlled by the owner of the mark with respect to the nature and quality of the goods or services on or in connection with which the mark is used."],[0,"The terms \"trade name\" and \"commercial name\" mean any name used by a person to identify his or her business or vocation."],[0,"The term \"trademark\" includes any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish his or her goods, including a unique product, from those manufactured or sold by others and to indicate the source of the goods, even if that source is unknown."],[0,"The term \"service mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish the services of one person, including a unique service, from the services of others and to indicate the source of the services, even if that source is unknown. Titles, character names, and other distinctive features of radio or television programs may be registered as service marks notwithstanding that they, or the programs, may advertise the goods of the sponsor."],[0,"The term \"certification mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person other than its owner, or"],[1,"(2) which its owner has a bona fide intention to permit a person other than the owner to use in commerce and files an application to register on the principal register established by this chapter,"],[0,"to certify regional or other origin, material, mode of manufacture, quality, accuracy, or other characteristics of such person's goods or services or that the work or labor on the goods or services was performed by members of a union or other organization."],[0,"The term \"collective mark\" means a trademark or service mark—"],[1,"(1) used by the members of a cooperative, an association, or other collective group or organization, or"],[1,"(2) which such cooperative, association, or other collective group or organization has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"and includes marks indicating membership in a union, an association, or other organization."],[0,"The term \"mark\" includes any trademark, service mark, collective mark, or certification mark."],[0,"The term \"use in commerce\" means the bona fide use of a mark in the ordinary course of trade, and not made merely to reserve a right in a mark. For purposes of this chapter, a mark shall be deemed to be in use in commerce—"],[1,"(1) on goods when—"],[2,"(A) it is placed in any manner on the goods or their containers or the displays associated therewith or on the tags or labels affixed thereto, or if the nature of the goods makes such placement impracticable, then on documents associated with the goods or their sale, and"],[2,"(B) the goods are sold or transported in commerce, and"],[1,"(2) on services when it is used or displayed in the sale or advertising of services and the services are rendered in commerce, or the services are rendered in more than one State or in the United States and a foreign country and the person rendering the services is engaged in commerce in connection with the services."],[0,"A mark shall be deemed to be \"abandoned\" if either of the following occurs:"],[1,"(1) When its use has been discontinued with intent not to resume such use. Intent not to resume may be inferred from circumstances. Nonuse for 3 consecutive years shall be prima facie evidence of abandonment. \"Use\" of a mark means the bona fide use of such mark made in the ordinary course of trade, and not made merely to reserve a right in a mark."],[1,"(2) When any course of conduct of the owner, including acts of omission as well as commission, causes the mark to become the generic name for the goods or services on or in connection with which it is used or otherwise to lose its significance as a mark. Purchaser motivation shall not be a test for determining abandonment under this paragraph."],[0,"The term \"colorable imitation\" includes any mark which so resembles a registered mark as to be likely to cause confusion or mistake or to deceive."],[0,"The term \"registered mark\" means a mark registered in the United States Patent and Trademark Office under this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, or the Act of March 19, 1920. The phrase \"marks registered in the Patent and Trademark Office\" means registered marks."],[0,"The term \"Act of March 3, 1881\", \"Act of February 20, 1905\", or \"Act of March 19, 1920\", means the respective Act as amended."],[0,"A \"counterfeit\" is a spurious mark which is identical with, or substantially indistinguishable from, a registered mark."],[0,"The term \"domain name\" means any alphanumeric designation which is registered with or assigned by any domain name registrar, domain name registry, or other domain name registration authority as part of an electronic address on the Internet."],[0,"The term \"Internet\" has the meaning given that term in section 230(f)(1) of title 47."],[0,"Words used in the singular include the plural and vice versa."],[0,"The intent of this chapter is to regulate commerce within the control of Congress by making actionable the deceptive and misleading use of marks in such commerce; to protect registered marks used in such commerce from interference by State, or territorial legislation; to protect persons engaged in such commerce against unfair competition; to prevent fraud and deception in such commerce by the use of reproductions, copies, counterfeits, or colorable imitations of registered marks; and to provide rights and remedies stipulated by treaties and conventions respecting trademarks, trade names, and unfair competition entered into between the United States and foreign nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1127?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1127. Construction and definitions; intent of chapter","tname":"Commerce and Trade","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(a)(2)"],"stext":{"head":"§45. Unfair methods of competition unlawful; prevention by Commission","paras":[[0,"(a) Declaration of unlawfulness; power to prohibit unfair practices; inapplicability to foreign trade"],[0,"(1) Unfair methods of competition in or affecting commerce, and unfair or deceptive acts or practices in or affecting commerce, are hereby declared unlawful."],[0,"(2) The Commission is hereby empowered and directed to prevent persons, partnerships, or corporations, except banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, common carriers subject to the Acts to regulate commerce, air carriers and foreign air carriers subject to part A of subtitle VII of title 49, and persons, partnerships, or corporations insofar as they are subject to the Packers and Stockyards Act, 1921, as amended [7 U.S.C. 181 et seq.], except as provided in section 406(b) of said Act [7 U.S.C. 227(b)], from using unfair methods of competition in or affecting commerce and unfair or deceptive acts or practices in or affecting commerce."],[0,"(3) This subsection shall not apply to unfair methods of competition involving commerce with foreign nations (other than import commerce) unless—"],[1,"(A) such methods of competition have a direct, substantial, and reasonably foreseeable effect—"],[2,"(i) on commerce which is not commerce with foreign nations, or on import commerce with foreign nations; or"],[2,"(ii) on export commerce with foreign nations, of a person engaged in such commerce in the United States; and"],[1,"(B) such effect gives rise to a claim under the provisions of this subsection, other than this paragraph."],[0,"If this subsection applies to such methods of competition only because of the operation of subparagraph (A)(ii), this subsection shall apply to such conduct only for injury to export business in the United States."],[0,"(4)(A) For purposes of subsection (a), the term \"unfair or deceptive acts or practices\" includes such acts or practices involving foreign commerce that—"],[1,"(i) cause or are likely to cause reasonably foreseeable injury within the United States; or"],[1,"(ii) involve material conduct occurring within the United States."],[0,"(B) All remedies available to the Commission with respect to unfair and deceptive acts or practices shall be available for acts and practices described in this paragraph, including restitution to domestic or foreign victims."],[0,"(b) Proceeding by Commission; modifying and setting aside orders"],[0,"Whenever the Commission shall have reason to believe that any such person, partnership, or corporation has been or is using any unfair method of competition or unfair or deceptive act or practice in or affecting commerce, and if it shall appear to the Commission that a proceeding by it in respect thereof would be to the interest of the public, it shall issue and serve upon such person, partnership, or corporation a complaint stating its charges in that respect and containing a notice of a hearing upon a day and at a place therein fixed at least thirty days after the service of said complaint. The person, partnership, or corporation so complained of shall have the right to appear at the place and time so fixed and show cause why an order should not be entered by the Commission requiring such person, partnership, or corporation to cease and desist from the violation of the law so charged in said complaint. Any person, partnership, or corporation may make application, and upon good cause shown may be allowed by the Commission to intervene and appear in said proceeding by counsel or in person. The testimony in any such proceeding shall be reduced to writing and filed in the office of the Commission. If upon such hearing the Commission shall be of the opinion that the method of competition or the act or practice in question is prohibited by this subchapter, it shall make a report in writing in which it shall state its findings as to the facts and shall issue and cause to be served on such person, partnership, or corporation an order requiring such person, partnership, or corporation to cease and desist from using such method of competition or such act or practice. Until the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, or, if a petition for review has been filed within such time then until the record in the proceeding has been filed in a court of appeals of the United States, as hereinafter provided, the Commission may at any time, upon such notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any report or any order made or issued by it under this section. After the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, the Commission may at any time, after notice and opportunity for hearing, reopen and alter, modify, or set aside, in whole or in part any report or order made or issued by it under this section, whenever in the opinion of the Commission conditions of fact or of law have so changed as to require such action or if the public interest shall so require, except that (1) the said person, partnership, or corporation may, within sixty days after service upon him or it of said report or order entered after such a reopening, obtain a review thereof in the appropriate court of appeals of the United States, in the manner provided in subsection (c) of this section; and (2) in the case of an order, the Commission shall reopen any such order to consider whether such order (including any affirmative relief provision contained in such order) should be altered, modified, or set aside, in whole or in part, if the person, partnership, or corporation involved files a request with the Commission which makes a satisfactory showing that changed conditions of law or fact require such order to be altered, modified, or set aside, in whole or in part. The Commission shall determine whether to alter, modify, or set aside any order of the Commission in response to a request made by a person, partnership, or corporation under paragraph 1 (2) not later than 120 days after the date of the filing of such request."],[0,"(c) Review of order; rehearing"],[0,"Any person, partnership, or corporation required by an order of the Commission to cease and desist from using any method of competition or act or practice may obtain a review of such order in the court of appeals of the United States, within any circuit where the method of competition or the act or practice in question was used or where such person, partnership, or corporation resides or carries on business, by filing in the court, within sixty days from the date of the service of such order, a written petition praying that the order of the Commission be set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Commission, and thereupon the Commission shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon such filing of the petition the court shall have jurisdiction of the proceeding and of the question determined therein concurrently with the Commission until the filing of the record and shall have power to make and enter a decree affirming, modifying, or setting aside the order of the Commission, and enforcing the same to the extent that such order is affirmed and to issue such writs as are ancillary to its jurisdiction or are necessary in its judgement to prevent injury to the public or to competitors pendente lite. The findings of the Commission as to the facts, if supported by evidence, shall be conclusive. To the extent that the order of the Commission is affirmed, the court shall thereupon issue its own order commanding obedience to the terms of such order of the Commission. If either party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts, or make new findings, by reason of the additional evidence so taken, and it shall file such modified or new findings, which, if supported by evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of its original order, with the return of such additional evidence. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court upon certiorari, as provided in section 1254 of title 28."],[0,"(d) Jurisdiction of court"],[0,"Upon the filing of the record with it the jurisdiction of the court of appeals of the United States to affirm, enforce, modify, or set aside orders of the Commission shall be exclusive."],[0,"(e) Exemption from liability"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/45?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§45. Unfair methods of competition unlawful; prevention by Commission","tname":"Commerce and Trade","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 52","url":"https://www.law.cornell.edu/uscode/text/15/52","subs":["(a)"],"by":{"0":"2"}},{"t":"reg","label":"36 Fed. Reg. 18,539","url":"https://www.govinfo.gov/link/fr/36/18539","by":{"0":"2"}},{"t":"reg","label":"37 Fed. Reg. 12,327","url":"https://www.govinfo.gov/link/fr/37/12327","by":{"0":"21"}},{"t":"reg","label":"39 Fed. Reg. 20,908","url":"https://www.govinfo.gov/link/fr/39/20908","by":{"0":"21"}},{"t":"reg","label":"45 Fed. Reg. 39,249","url":"https://www.govinfo.gov/link/fr/45/39249","by":{"0":"15"}},{"t":"reg","label":"49 Fed. Reg. 22,831","url":"https://www.govinfo.gov/link/fr/49/22831","by":{"0":"15"}},{"t":"reg","label":"52 Fed. Reg. 26,691","url":"https://www.govinfo.gov/link/fr/52/26691","by":{"0":"15"}},{"t":"reg","label":"55 Fed. Reg. 3268","url":"https://www.govinfo.gov/link/fr/55/3268","by":{"0":"15"}}]};